```python
"""A queue-backed worker thread that hands each item to a callback."""

import logging
import queue
import threading

log = logging.getLogger(__name__)

_SHUTDOWN = object()


class QueueWorker:
    """Consumes items from a queue.Queue on a background thread.

    Each item is passed to `callback`. Exceptions raised by the callback are
    logged and swallowed so one bad item cannot kill the worker.
    """

    def __init__(self, callback, q=None, name="queue-worker", daemon=True):
        self.callback = callback
        self.queue = q if q is not None else queue.Queue()
        self._thread = threading.Thread(target=self._run, name=name, daemon=daemon)
        self._started = False

    def start(self):
        if self._started:
            raise RuntimeError("worker already started")
        self._started = True
        self._thread.start()
        return self

    def put(self, item, block=True, timeout=None):
        self.queue.put(item, block=block, timeout=timeout)

    def _run(self):
        while True:
            item = self.queue.get()
            try:
                if item is _SHUTDOWN:
                    return
                self.callback(item)
            except Exception:
                log.exception("callback failed for item %r", item)
            finally:
                self.queue.task_done()

    def join_queue(self):
        """Block until every item queued so far has been processed."""
        self.queue.join()

    def stop(self, timeout=None):
        """Signal shutdown and wait for the thread to finish."""
        if not self._started:
            return
        self.queue.put(_SHUTDOWN)
        self._thread.join(timeout)

    def __enter__(self):
        return self.start()

    def __exit__(self, *exc):
        self.stop()
        return False


if __name__ == "__main__":
    logging.basicConfig(level=logging.INFO)
    with QueueWorker(lambda n: print(f"got {n} -> {n * n}")) as worker:
        for i in range(5):
            worker.put(i)
        worker.join_queue()
```

The sentinel is a module-private `object()` rather than `None` so `None` stays a legal payload. `stop()` queues the sentinel behind pending work, so anything already enqueued still gets processed; call it from a `finally` or use the context manager. For multiple consumers you'd need one sentinel per thread.
